// The page's labels, palette and limits, in every language the product has.
//
// Generated by tools/bootdata.py out of texts.py until the Python half was
// deleted. Both are gone, so this file is the source now rather than a copy of
// one: edit it here, and mind that a label may also be read by the firmware's
// own table - see firmware/vorlaut/texts.h and tests/test_texts.py.
//
// Both languages travel together on purpose. There is no server to pick one
// before the page loads, so the choice stays the reader's.
//
// The generator used to guarantee that the two languages held the same keys.
// tests/browser/boot_data.test.mjs is what is left of that guarantee, and it
// is the reason a missing translation still fails rather than showing a blank
// button to whoever reads the language nobody checked.

export const LANGUAGES = ["de", "en"];
export const DEFAULT_LANGUAGE = "en";
export const PALETTE = ["#3B5BDB", "#159947", "#9B7BFF", "#FF8BC7", "#FF6B35"];
export const LIMITS = {"maxSets": 25, "maxActive": 5};

